    ("這只允許被執行被限定的次數", "此操作只能執行有限次數"),
    ("這是沒有用的文字位置，跟最後戰一無任何關聯性。", "這是毫無用處的佔位文字，完全沒有解釋任何與最後戰役相關的內容！"),
    ("劇烈的地殼活動破壞了奧雷利亞星球，並在星球表面造成一個巨大的裂隙。這似乎與黑色軍團在冰雕的儀式有所關聯。", "大規模地殼活動重創奧雷利亞星球，在其表面撕開巨大裂隙。這似乎與黑色軍團在冰工廠舉行的儀式有關。"),
    ("這個大門實在沒有什麼地方跟天使有關聯。", "這座門幾乎沒有任何天使意味。"),
    ("遠比搭配的同套終結者裝甲還要陳舊，此傳送裝備是血鴉戰團最古老的上古聖物之一。對於這樣一個至少可追溯至大聖戰的裝置如何與相較顯得年輕的戰團有所關聯，人們可說充滿許多疑問。", "這台傳送器比其所在的終結者裝甲還要古老，是血鴉戰團最古老的聖物之一。許多人質疑，一件至少可追溯到大遠征時期的裝置，為何會與一個相對年輕的戰團聯繫在一起。"),
    ("突擊部隊裝備噴射背包，可以快速的接近使用近戰攻擊。透過強化噴射跳躍背包可以得到自殺跳躍技能，並可得到老大頭領。", "裝備跳躍背包的突擊部隊。擅長迅速接近並迫使遠程單位進入近戰。可升級改良火箭背包，以使用炸彈小子。也可升級老大頭目。"),
    ("突擊部隊裝備噴射背包，可以快速的接近使用近戰攻擊。透過強化跳躍背包可以得到「自殺跳躍」技能，並可得到老大頭領。", "裝備跳躍背包的突擊部隊。擅長迅速接近並迫使遠程單位進入近戰。可升級改良跳躍背包，以使用「自殺跳躍」。也可升級老大頭目。"),
    ("突擊部隊裝備噴射背包，可以快速的接近使用近戰攻擊。透過強化跳躍背包可以得到自殺跳躍技能，並可得到老大頭領。", "裝備跳躍背包的突擊部隊。擅長迅速接近並迫使遠程單位進入近戰。可升級改良火箭背包，以使用炸彈小子。也可升級老大頭目。"),
    ("胞子囊包用以孕育並傳送蟲族單位。蟲胞擁有精確感應器，敵人過於接近時將觸發開啟。", "菌囊地雷用於孕育並傳送泰倫蟲族單位。地雷具備敏銳感應器，敵人過於接近時即使尚未成熟也會觸發開啟。"),
    ("敵人過於接近時將繁衍胞子囊包", "生成一枚菌囊地雷，敵人過於接近時會開啟"),
