    ("以做為對其他星球的警告", "以警示周邊星區"),
    ("審判庭並不是這星區的新面孔，不久前以受肯定的態度解決了昔蘭尼的問題。", "審判庭對這個星區並不陌生，不久前便以核准的方式處理了昔蘭尼問題。"),
    ("昔蘭尼的多數知識全被惡魔審判庭列為機密，是個貧瘠的世界，數十年前遭審判庭肅淨。", "昔蘭尼的大部分資料都被惡魔審判庭列為機密。它如今是貧瘠而布滿灰燼的殘骸，數十年前已被審判庭徹底淨化。"),
    ("大型毛細塔從泰豐的地面升起以餵食泰倫蟲巢艦隊。", "巨大的毛細塔從泰豐地表升起，將生物質輸送給泰倫蟲巢艦隊。"),
    ("這座溪谷現在成為泰豐的死亡地點。一座巨大毛細塔從這裡升起，餵食蟲巢艦隊 。這是充滿泰倫蟲族的地方，它們保護這塊極其重要的地區。", "這座溪谷如今已成為泰豐的死亡之地。一座巨大毛細塔從這裡升起，向蟲巢艦隊輸送生物質。此處遍布泰倫蟲族，它們正守護這塊極其重要的地區。"),
    ("指揮官，蟲巢艦隊透過這些巨大的毛細塔餵食。", "指揮官，蟲巢艦隊正透過這些巨大的毛細塔攝取生物質。"),
    ("我們已經確認了蟲巢船艦為了從最大的毛細塔那餵食下降進入大氣層的報告。", "我們已確認報告：蟲巢艦船正在下降進入大氣層，準備從最大的毛細塔攝取生物質。"),
    ("這些巨大的塔樓把生體物質灌注到這些餵食者船艦中。", "這些巨塔會將生物質注入攝食艦船。"),
    ("從毛細塔繼續餵食。", "繼續從毛細塔攝取生物質。"),
    ("蟲巢吞噬整個宇宙。它們的目標就是餵食自己並成長，在整個銀河被耗盡之前它們是不會停止的。", "蟲巢吞噬整個世界。它們的目的就是攝食並成長，在整個銀河被耗盡之前絕不會停止。"),
    ("只要幾個禮拜的時間，巨大的毛細塔將會從表面成長，而蟲巢艦隊將完全吞沒這個宇宙的所有生物。", "再過幾週，巨大的毛細塔就會從地表升起，蟲巢艦隊將吞噬這個世界上的一切生物。"),
    ("把生體毒素弄到毛細塔是眼前最重樣要的事情。", "眼下最重要的事，就是把生物毒素送進毛細塔。"),
    ("靈族方舟世界 -- 巨大的漂流恆星太空廢船對一個曾經統治銀河系的民族來說，是他們最後倖存者的家 -- 遍及在恆星各處。現在靈族在毀滅的斷崖上搖搖晃晃，並且必須不斷地戰鬥來對抗獸人。", "靈族方舟世界是巨大的星際漂流艦，承載著這個曾經統治銀河民族的最後倖存者，散布於群星之間。如今靈族徘徊在毀滅邊緣，必須不斷戰鬥以抵抗獸人。"),
    ("生體物質", "生物質"),
    ("蟲巢艦隊正要降落到%1PLANET%的大氣層，準備從最大的毛細塔進食。除非他們遭消滅，否則異形會利用這個方法將星球消耗殆盡。", "蟲巢艦隊正要降入%1PLANET%的大氣層，準備從最大的毛細塔攝取生物質。除非它們被消滅，否則異形將以這種方式把星球吞噬殆盡。"),
    ("你只有一次機會趁蟲巢艦隊在泰豐進食時來給予它致命的打擊。你必須打擊供它餵食的巨大毛細塔底部，並注入在天使熔爐所製造的毒液。來自梅里迪安的星界軍精英將提供支援，無論如何，這都是場終極大戰。", "你只有一次機會趁蟲巢艦隊在泰豐攝食時給予它致命打擊。你必須攻擊供它攝取生物質的巨大毛細塔底部，並注入天使熔爐製造的毒液。來自梅里迪安的星界軍精英將提供支援，無論如何，這都是最後決戰。"),
    ("泰倫蟲族威脅度", "泰倫蟲族威脅"),
    ("卡德利斯泰倫蟲族威脅度", "卡德利斯泰倫蟲族威脅"),
    ("泰豐泰倫蟲族威脅度", "泰豐泰倫蟲族威脅"),
    ("為死者帶來長眠，該承受者必須承擔，每一個方舟世界失去的靈魂，既使戰死也義無反顧。", "為死者帶來長眠。承擔此責者必須背負方舟世界每一個逝去靈魂的重量，即使戰死也在所不辭。"),
    ("審判庭的船艦全都朝這星區而來…它…無論你是死在我們手上…或…他們手中都無所謂了。", "審判庭艦隊正全速趕往這個星區…所以…無論你死在我們手上…還是他們手中…都無所謂了。"),
    ("恕我直言，阿巴頓，讓凱拉斯親手毀滅血鴉是否更為明智？", "恕我直言，阿巴頓大人，讓凱拉斯親手毀滅血鴉是否更為明智？"),
    ("滅絕令將自行完成；血鴉的靈魂歸您所有，戰帥阿巴頓。", "滅絕令會自行完成；血鴉的靈魂將歸您所有，戰帥阿巴頓。"),
    ("不是，是太空廢船，如果我沒弄錯的話，是腐屍審判。", "不是，是太空廢船。如果我沒弄錯，是腐屍審判號。"),
    ("你的手法真是毒辣到令人吃驚，羅奈恩，你真的是來自先知之城－烏維斯方舟世界嗎？", "你的手段毒辣得令人吃驚，羅奈恩。你真的是來自先知之城、烏斯維方舟世界嗎？"),
    ("藥劑師葛藍在腐屍審判號的可怕經歷前便是裝備此劍上戰場，在他稍早的生涯中，葛藍是個受尊崇的突擊戰士，殺害無數的獸人。", "在腐屍審判號的可怕經歷之前，藥劑師加蘭便曾持此劍上陣。早年生涯中，加蘭是一位備受尊崇的突擊戰士，斬殺過無數獸人。"),
    ("那簡單－我們突擊這支部隊，然後審問他們，一直到獲得我們需要的資訊。", "很簡單：我們突擊這支部隊，然後審問他們，直到取得需要的情報。"),
    ("貝坦方舟世界的靈族？真是幸運！嘿，是我的族人！", "貝爾坦方舟世界的靈族？真幸運！嘿，是我的族人！"),
    ("推論叛徒的儀式蒙蔽惡魔審判庭，而未發現泰倫蟲族逼近。", "推定叛徒的儀式蒙蔽了惡魔審判庭，使其未能發現泰倫蟲族逼近。"),
    ("傳送室帶領我們前往太空廢船－腐屍審判。", "傳送室會帶我們前往太空廢船「腐屍審判號」。"),
    ("肅清利比斯-尼賴斯前哨的基因竊取者異端時，便是使用這些受尊崇的武器。在殲滅成千的異族之後，巨爪回到了帝國之拳的一名工匠手中，他修復並並化了這些武器。", "肅清利比斯-尼賴斯前哨的基因竊取者異端時，使用的正是這些受尊崇的武器。在殲滅成千異族之後，巨爪回到一名帝國之拳工匠手中，由他修復並淨化。"),
    ("這套受尊崇的終結者裝甲數世紀以來為血鴉的榮譽護衛所使用。被送至工匠佐達諾斯後，便再也沒有返還 - 工匠大師拒絕將如此貴重之物信任地託付給守衛。", "這套受尊崇的終結者裝甲數世紀以來由血鴉榮譽衛隊使用。送至工匠佐達諾斯手中後，它便再也沒有返還，因為工匠大師拒絕將如此珍貴之物託付給衛隊。"),
    ("強大的混沌動力裝甲，擁有祖先的魔法，並刻蝕著對黑暗諸神的禱文。", "強大的混沌動力裝甲，蘊含遠古咒法，並刻有獻給黑暗諸神的禱文。"),
    ("施展魔法導彈！", "施展靈能導彈！"),
    ("我施放魔法導彈！", "我施放靈能導彈！"),
    ("魔法導彈", "靈能導彈"),
    ("那個低劣魔法師不會再煩擾我們。", "那個低劣巫師不會再煩擾我們。"),
    ("她召喚扭曲魔法了！", "她召喚亞空間巫術了！"),
    ("扭曲魔法", "亞空間巫術"),
    ("魔法兵在那裡。", "靈能者在那裡。"),
    ("在他使出魔法前趕快攻擊他。", "趁他施展巫術前趕快攻擊他。"),
    ("法術對她沒有用", "靈能對她沒有用"),
    ("法術攻擊！", "靈能攻擊！"),
    ("法術救不了他們", "靈能救不了他們"),
    ("靈能大師，先知可以支援並施展法術來增強我方小隊的近戰攻擊及防禦。", "靈能大師，先知可以支援部隊，並施展靈能力強化我方小隊的近戰攻擊與防禦。"),
    ("先知是強大的靈能大師，擔任支援施法者，可用法術干擾敵人近戰並強化部隊。", "先知是強大的靈能大師，擔任支援型靈能者，可用靈能力干擾敵人近戰並強化部隊。"),
    ("戰鬥靈能者，專精於法術型傷害與前線作戰。", "戰鬥靈能者，專精於靈能傷害與前線作戰。"),
    ("攻擊型靈能者，專精傷害法術與前線戰鬥。", "攻擊型靈能者，專精靈能傷害與前線戰鬥。"),
    ("你選擇了一位術士指揮官，他是徒手戰鬥專家，可以攻擊一定距離外的敵人，並擁有將敵人擊退或拉近的法術，同時可以隱蔽鄰近的盟友。", "你選擇了一位術士指揮官。他是近身戰專家，可以攻擊一定距離外的敵人，並擁有擊退或拉近敵人的靈能力，同時可以隱蔽鄰近盟友。"),
    ("你選擇了術士指揮官。他是近身戰專家，能從一定距離外延展攻擊。他的法術可以擊退敵人或將敵人拉向自己。術士也能讓附近盟友隱形。", "你選擇了術士指揮官。他是近身戰專家，能從一定距離外延展攻擊。他的靈能力可以擊退敵人或將敵人拉向自己。術士也能讓附近盟友隱形。"),
    ("你選擇了先知指揮官。她的懸浮法術可以將整支小隊抬到空中，讓其他小隊攻擊他們。你可以在懸浮之刃上找到此能力。", "你選擇了先知指揮官。她的懸浮靈能力可以將整支小隊抬到空中，讓其他小隊攻擊他們。你可以在懸浮之刃上找到此能力。"),
    ("你選擇了一位術士士指揮官", "你選擇了一位術士指揮官"),
    ("召喚大規模的魔法鎖鍊", "召喚大規模的亞空間鎖鏈"),
    ("這些祭服鑲嵌邪惡的法術", "這些祭服嵌有邪惡咒法"),
    ("發射毀滅性的魔法球", "發射毀滅性的亞空間能量球"),
    ("血魔法", "血祭儀式"),
    ("魔法使用者", "施法者"),
    ("這些法袍擁有邪惡的魔法與保護", "這些法袍擁有邪惡咒法與防護"),
    ("黑暗魔法吸取能量時將使該單位漂浮空中", "黑暗咒法汲取能量時會使該單位漂浮到空中"),
    ("其黑暗魔法可使單位漂浮空中並汲取生命", "其黑暗咒法可使單位漂浮到空中並汲取生命"),
    ("腐化魔法", "腐化咒法"),
    ("會以魔法改變持有者身體物質的性質", "會以咒法改變持有者身體物質的性質"),
    ("魔法配方", "咒法配方"),
    ("魔法藍", "巫術藍"),
    ("俺討厭你的魔法，也討厭你！", "俺討厭你的巫術，也討厭你！"),
    ("以我們研發出來的毒餵食它。", "用我們研發出的毒素餵給它。"),
    ("這是餵食蟲巢的有毒生物質。", "這是供蟲巢攝取的有毒生物質。"),
    ("與我為敵的下場就是將你的靈魂餵食成千的疫病。", "與我為敵的下場，就是讓你的靈魂餵養成千疫病。"),
    ("一個準備餵食蛆的異形。", "一個準備餵蛆的異形。"),
    ("用他們的靈魂餵食色孽！", "用他們的靈魂餵養色孽！"),
    ("這些所謂的士兵全都餵食給蟲群了。", "這些所謂的士兵全都被送去餵蟲群了。"),
    ("我們要餵食蟲巢嗎？", "我們要餵養蟲巢嗎？"),
    ("拿他們…餵食恐虐！", "拿他們…獻給恐虐！"),
    ("餵食…血神！", "供奉…血神！"),
    ("將痛苦餵食血神。", "將痛苦獻給血神。"),
    ("腐屍審判。", "腐屍審判號。"),
    ("法術大師", "靈能大師"),
    ("提升所有法師的攻擊法術。視法術而有不同變化，包括提升傷害、範圍效果或攻擊次數。", "提升所有施法者的攻擊型靈能力。具體效果依能力而定，包括提升傷害、範圍效果或攻擊次數。"),
    ("提升奈若斯所有的攻擊法術。施展滅亡雷劈時，將發射兩次。", "提升奈若斯所有的攻擊型靈能力。施展滅亡雷劈時，將發射兩次。"),
    ("提升法師所有的攻擊法術。施展滅亡雷劈時，將發射兩次。", "提升施法者所有的攻擊型靈能力。施展滅亡雷劈時，將發射兩次。"),
