    ("這一強大法術", "這一強大靈能力"),
    ("先知是靈能大師，也是支援施法者，可用法術擾亂近戰並強化部隊。", "先知是靈能大師，也是支援型靈能者，可用靈能力擾亂近戰並強化部隊。"),
    ("善於以傷害與破壞性法術突破敵軍陣型。", "善於以傷害與破壞性靈能力突破敵軍陣型。"),
    ("靈族靈能者的法術", "靈族靈能者的靈能力"),
