    ("高衝撃", "高衝擊"),
    ("戰爭頭目獲得裝甲加成，近戰攻擊他的敵人獲得傷害。", "戰爭頭目獲得裝甲加成，近戰攻擊他的敵人會受到傷害。"),
    ("血旗獲得裝甲加成，近戰攻擊他的敵人獲得傷害。", "血旗獲得裝甲加成，近戰攻擊他的敵人會受到傷害。"),
