    ("Their untrained psychic mind has met a suitable end.", "他們未受訓的靈能心智迎來了合適的結局。"),
    ("An excellent shot. It suffices.", "漂亮的一擊。足夠了。"),
    ("We have shattered the building.", "我們已粉碎那座建築。"),
    ("We have made rubble of it.", "我們已將它化為瓦礫。"),
    ("The vehicle is down. Finish off any that flee.", "載具倒下了。解決所有逃跑者。"),
    ("I will not accept this.", "我不能接受。"),
    ("So they resist us.", "原來他們還在抵抗我們。"),
    ("The pain grows.", "痛苦正在增長。"),
    ("We are assailed.", "我們遭到攻擊。"),
    ("They are attacking from range.", "他們正在遠距離攻擊。"),
    ("The dance of blades begins!", "刀刃之舞開始！"),
    ("They wish to try our swords.", "他們想試試我們的劍。"),
    ("It is an ambush.", "這是伏擊。"),
    ("My attacker remains hidden.", "攻擊我的敵人仍然隱藏著。"),
    ("A primitive mind assails me.", "一個原始心智正在攻擊我。"),
    ("I have drawn the vehicle's attention.", "我引起了載具的注意。"),
    ("We are easy targets until we close the gap.", "在拉近距離前，我們是好打的目標。"),
    ("We are under a psychic onslaught.", "我們正在承受靈能猛攻。"),
    ("Daughters, beware the inaccurate weaponry of our foes.", "女兒們，當心敵人不精準的武器。"),
    ("We are beset with flame.", "我們被火焰包圍。"),
    ("We are under barrage.", "我們正在遭受彈幕。"),
    ("Keep us moving. Strike back as you can.", "讓我們保持移動。能還擊就還擊。"),
    ("Our craft takes heavy blows from the eneny.", "我們的載具正遭受敵人重擊。"),
    ("The humans grow presumptuous.", "人類越發放肆。"),
    ("The Imperials invite their own destruction.", "帝國人是在自取滅亡。"),
    ("Brutish Orks strike at us.", "野蠻獸人正在攻擊我們。"),
    ("We must teach these Orks their place.", "我們必須教會這些獸人自己的位置。"),
    ("Come human! Show me what you think you know of war!", "來吧，人類！讓我看看你以為自己懂得什麼戰爭！"),
    ("The Space Marines press their attack.", "星際戰士正在加緊攻勢。"),
    ("The Great Devourer sends its atrocities against us.", "大吞噬者派出它的暴行來對付我們。"),
    ("Drones of the Hive Mind scuttle toward us.", "蟲巢意志的奴僕正爬向我們。"),
    ("I return, ready for vengeance.", "我回來了，準備復仇。"),
    ("I return to the field.", "我重返戰場。"),
    ("Exarch Tyrea's path is renewed.", "大能者泰蕾雅的道途已更新。"),
    ("Let our foes hear their doom in my howl.", "讓敵人在我的嚎叫中聽見自己的毀滅。"),
    ("Our swords are keen and our souls are prepared.", "我們的劍鋒銳，靈魂已準備。"),
    ("Join us, Banshee.", "加入我們，女妖。"),
    ("The she-warriors grow in number.", "女戰士的人數增加了。"),
    ("From the forge of Vaul to the Banshee's hand.", "從沃爾的熔爐到女妖之手。"),
    ("The Banshee howls most fiercely on this day.", "今日女妖嚎叫得最為猛烈。"),
    ("I shall put the Temple's gifts to good use.", "我會善用神殿的贈禮。"),
    ("My blade is honed, Farseer.", "我的刀刃已磨利，先知。"),
    ("Our vehicle is in jeopardy.", "我們的載具陷入危險。"),
    ("There is difficulty in evading.", "規避變得困難。"),
    ("The wraithbone has been breached.", "幽冥骨已被擊穿。"),
    ("Our flight has ended, our wings clipped.", "我們的飛行已結束，羽翼被剪斷。"),
    ("The targeting matrix has shattered!", "瞄準矩陣已碎裂！"),
    ("Abandon the vehicle!", "棄車！"),
    ("Healing station deploying.", "治療站正在部署。"),
    ("Brothers, new orders.", "兄弟們，新命令。"),
    ("Destroy them!", "摧毀他們！"),
    ("No mercy! No respite!", "絕不留情！絕不停歇！"),
