    ("Target confirmed! Engaging!", "目標確認！交戰！"),
    ("Death before dishonor!", "寧死不辱！"),
    ("We must finish this later.", "我們之後必須完成此事。"),
    ("There are more urgent matters.", "還有更緊急的事。"),
    ("I have my target.", "我已有目標。"),
    ("I make my strike.", "我發動打擊。"),
    ("I shall take my first opening.", "我會抓住第一個破綻。"),
    ("I will rid us of this irritation.", "我會替我們除掉這個煩擾。"),
    ("Courage. After all, the Exarchs are with us.", "勇氣。畢竟，大能者與我們同在。"),
    ("I stand with the Craftworld again, it seems.", "看來我又與方舟世界並肩了。"),
    ("Do not confuse glory with victory.", "不要把榮耀與勝利混為一談。"),
    ("We will survive.", "我們會活下來。"),
    ("They shall fall.", "他們會倒下。"),
    ("Confound their strategy and they shall die soon enough.", "擾亂他們的戰略，他們很快就會死。"),
    ("Even fallen, we outmatch them.", "即便倒下，我們也勝過他們。"),
    ("They have already made fatal errors.", "他們已犯下致命錯誤。"),
    ("Grenades aloft.", "手雷升空。"),
    ("The heat of the stars in their midst.", "星辰之熱落入他們之中。"),
    ("Naught but scattered ashes.", "只剩四散灰燼。"),
    ("I send them warm tidings.", "我送給他們溫熱的問候。"),
    ("I must tend wounds.", "我必須處理傷口。"),
    ("A moment for healing.", "片刻治療。"),
    ("Thought flows and flesh mends.", "思緒流動，血肉癒合。"),
    ("I can heal as well as kill.", "我能治癒，也能殺戮。"),
    ("I take aim.", "我正在瞄準。"),
    ("The smallest vulnerability is enough.", "最微小的破綻也已足夠。"),
    ("Precision follows patience.", "精準源於耐心。"),
    ("One faultless shot.", "完美一擊。"),
    ("A time to conceal, a time to reveal.", "有隱匿之時，也有顯現之時。"),
    ("Now they may look at me if they wish.", "現在他們想看我就看吧。"),
    ("No trace of my passage.", "我的行蹤不留痕跡。"),
    ("Let our foe's very eyes deceive them.", "讓敵人的雙眼欺騙他們自己。"),
    ("To the fight.", "投入戰鬥。"),
    ("In for the kill.", "前去擊殺。"),
    ("So kind to set this glory before me.", "真是好心，把這份榮耀擺在我面前。"),
    ("Let silence take those guns.", "讓寂靜吞沒那些槍炮。"),
    ("At any cost.", "不惜任何代價。"),
    ("The hour has come.", "時刻已到。"),
    ("It is not long for this world.", "它在此世已時日無多。"),
    ("I have marked it for destruction.", "我已將它標記為毀滅。"),
    ("I must be careful with this one.", "面對這個，我必須謹慎。"),
    ("I shall thin out the soldiery.", "我會削減那些士兵。"),
    ("This beast will perish.", "這頭野獸將會滅亡。"),
    ("Shall I rid us of their conjuror?", "要我替我們除掉他們的咒法者嗎？"),
    ("I can kill those in the windows.", "我能殺死窗後的人。"),
    ("You have seen victory here, Farseer?", "先知，你已看見此地的勝利了嗎？"),
    ("As ever, I strike true.", "一如既往，我命中無誤。"),
    ("The battle calls us.", "戰鬥在召喚我們。"),
    ("Stifle their weapon.", "壓制他們的武器。"),
    ("Rangers, focus on the commander.", "遊俠，集中瞄準指揮官。"),
    ("Seek out its weak points.", "找出它的弱點。"),
    ("We cannot allow its psychic mischief here.", "我們不能容許它在此施展靈能把戲。"),
    ("Fire at any you see within.", "向你看見的任何裡面敵人開火。"),
    ("Bring down their transport.", "擊毀他們的運輸載具。"),
    ("Hold fast, Rangers.", "堅守，遊俠。"),
    ("All weapons, fire.", "所有武器，開火。"),
    ("Pursue it swiftly.", "迅速追擊它。"),
    ("Match it move for move.", "逐步跟上它的動作。"),
    ("Bring it to bay.", "把它逼入絕境。"),
    ("The humans have made themselves inconvenient.", "人類把自己變成了麻煩。"),
    ("I detest dallying with Orks, but alas.", "我厭惡與獸人糾纏，但也只能如此。"),
    ("Let us give them the martyrdom they desire.", "讓我們賜予他們渴望的殉道。"),
    ("Slay the locusts.", "殺死蝗蟲。"),
    ("Where their contagion spreads, worlds die.", "他們的感染蔓延之處，世界便會死去。"),
    ("I will bring them the battle.", "我會把戰鬥帶給他們。"),
    ("I will seek out the foe.", "我會找出敵人。"),
    ("I must blaze a trail.", "我必須開出道路。"),
    ("We have an appointment to keep.", "我們有約要赴。"),
    ("We are the advance guard.", "我們是先鋒。"),
    ("Pursue any foe we encounter.", "追擊遇到的任何敵人。"),
    ("The anger of Vaul is ready.", "沃爾之怒已準備就緒。"),
