    ("Our Grav platform is prepared.", "我們的反重力平台已準備好。"),
    ("The wraithbone shall be sculpted.", "幽冥骨將被塑造。"),
    ("This will serve us well.", "這會好好為我們效用。"),
    ("Bring forth the Wraithbone.", "喚出幽冥骨。"),
    ("The wraithsong is sung.", "幽冥之歌已唱響。"),
    ("We shall take it.", "我們會奪下它。"),
    ("It stands in Eldar hands.", "它已在靈族手中。"),
    ("We shall claim it, lest the enemy do so.", "我們要奪取它，以免敵人得手。"),
    ("We control this terrain.", "我們控制此地形。"),
    ("We will expropriate it.", "我們會徵用它。"),
    ("It is ours to lose now.", "現在它已屬於我們，可能失去的也是我們。"),
    ("From under their very noses.", "就在他們眼皮底下。"),
    ("I shall secure it.", "我會確保它。"),
    ("The spoils of war.", "戰爭的戰利品。"),
    ("I have assumed possession.", "我已取得所有權。"),
    ("I am beaten.", "我被擊敗了。"),
    ("I shall reduce it to ruin.", "我會將它化為廢墟。"),
    ("I can do no more.", "我已無能為力。"),
    ("I have tried to make amends.", "我已試圖彌補。"),
    ("I trust this will please the Farseer.", "我相信這會令先知滿意。"),
    ("This is a sinister development.", "這是不祥的進展。"),
    ("Excellent. Keep me informed.", "很好。隨時通知我。"),
    ("Our gods curse us.", "我們的神詛咒了我們。"),
    ("Confirmed.", "確認。"),
    ("Naturally.", "自然。"),
    ("Yes, I see.", "是，我明白。"),
    ("I shall not fail.", "我不會失敗。"),
    ("As I am ordered.", "遵照命令。"),
