    ("It seems I still have lessons to learn.", "看來我仍有課要學。"),
    ("I will enter at once.", "我會立即進入。"),
    ("Afoot once more.", "再次徒步。"),
    ("I shall strike at our foes from the openings.", "我會從開口處打擊敵人。"),
