    ("There is no more to gain here.", "這裡已無更多可得。"),
    ("I begin to doubt our strategy.", "我開始懷疑我們的戰略。"),
    ("If this was his vision, I mislike it.", "若這是他的幻象，我不喜歡。"),
    ("It is beyond toleration.", "這已不可容忍。"),
    ("Only a fool would choose to die here.", "只有蠢人才會選擇死在這裡。"),
    ("This is madness.", "這是瘋狂。"),
    ("It is my chance, come at last.", "我的機會終於來了。"),
    ("See how a cooled ember can rekindle.", "看看冷卻的餘燼如何重燃。"),
