    ("Away, quickly.", "離開，快。"),
    ("Vanish like mist.", "如霧般消失。"),
    ("Another time.", "改日再戰。"),
    ("I am well. I hope our other forces can say the same?", "我安然無恙。希望我們其他部隊也能這麼說？"),
    ("I remain unseen.", "我仍未被看見。"),
    ("I am Ronahn.", "我是羅南。"),
    ("What would you have of me?", "你要我做什麼？"),
    ("I am ready.", "我準備好了。"),
    ("You shall not find me unprepared.", "你不會發現我毫無準備。"),
