    ("The green tide crests.", "綠潮高漲。"),
    ("Even the blind could track these Orks.", "即便盲者也能追蹤這些獸人。"),
    ("It is the Space Marines.", "是星際戰士。"),
    ("Be careful of these humans. They are far more fearsome than their brethren.", "小心這些人類。他們比自己的同胞可怕得多。"),
