    ("I shall refrain.", "我會克制。"),
    ("We are to remain here.", "我們要留在這裡。"),
    ("One moment.", "稍等。"),
    ("I will keep observing.", "我會繼續觀察。"),
    ("Hold just here.", "就在這裡停下。"),
