    ("I am under assault.", "我正遭受攻擊。"),
    ("The Space Marines have come to 'cleanse' us.", "星際戰士來「淨化」我們了。"),
    ("The Emperor's automatons descend.", "帝皇的自動人偶降臨了。"),
