    ("I return to the front.", "我重返前線。"),
    ("My fate is not yet sealed.", "我的命運尚未封定。"),
    ("You may call me outcast, but I am Ronahn and I will serve.", "你可以稱我為放逐者，但我是羅南，我會效命。"),
    ("Your Pathfinder is standing by.", "你的尋路者待命中。"),
    ("The Ranger squad stands assembled.", "遊俠小隊已集結。"),
    ("We have recruits.", "我們有新兵。"),
    ("Reinforcements have reached us.", "增援已抵達我們這裡。"),
    ("Bravery without weaponry means little.", "沒有武器的勇氣意義不大。"),
    ("In the wilderness, one's tools are one's life.", "在荒野中，工具就是性命。"),
    ("I am ground to a keener edge.", "我被磨得更加鋒利。"),
    ("I have summoned all my resources.", "我已調集所有資源。"),
