    ("Our talons have been clipped.", "我們的利爪被剪斷了。"),
    ("Falcon, you have served us well.", "獵鷹，你已很好地為我們效命。"),
    ("Moving to engage!", "正在前往交戰！"),
    ("Brothers, bring that structure down.", "兄弟們，摧毀那座建築。"),
    ("Getting low on strength!", "力量快耗盡了！"),
    ("This could be the end of me!", "這可能就是我的終點！"),
