    ("None may stand against Space Marines!", "無人能抵擋星際戰士！"),
    ("Face the Emperor's wrath!", "面對帝皇的怒火！"),
    ("We cannot finish this now.", "我們現在無法完成此事。"),
    ("It must lie fallow a while longer.", "它還必須再閒置一段時間。"),
    ("They are merely the stone I sharpen my skills upon.", "他們不過是我磨礪技藝的磨刀石。"),
    ("They shall fall into my trap.", "他們會落入我的陷阱。"),
    ("I will see what they are made of.", "我會看看他們是什麼材料做的。"),
    ("I am most dangerous when wounded.", "受傷時的我最危險。"),
    ("Like true hunters we must savor the chase no less than the kill.", "如真正獵人一般，我們必須品味追獵，不亞於擊殺。"),
    ("No mercy for prey.", "對獵物絕不留情。"),
    ("Let us give them a taste of what awaits.", "讓他們嚐嚐等待自己的滋味。"),
    ("They feel the fingers of death.", "他們感到死亡的手指。"),
    ("They are ill at ease.", "他們心神不寧。"),
    ("They will die quickly. Perhaps too quickly.", "他們會死得很快。也許太快。"),
    ("Scatter them like chaff.", "像糠秕一樣驅散他們。"),
    ("I have some venom left.", "我還剩一些毒液。"),
    ("Healing is also an art.", "治療也是一門藝術。"),
    ("Corpses make poor soldiers.", "屍體當不了好士兵。"),
    ("Endure a while longer.", "再忍耐片刻。"),
    ("When they feel it, it shall already be too late.", "等他們感覺到時，一切已經太遲。"),
    ("They shall dangle on my lure.", "他們會掛在我的誘餌上。"),
    ("The more they move, the greater the pain.", "他們動得越多，痛苦就越大。"),
    ("Let them struggle.", "讓他們掙扎。"),
    ("I skim the Warp.", "我掠過亞空間。"),
