    ("I have chosen my prize.", "我已選定獎品。"),
    ("With pleasure.", "樂意之至。"),
    ("It would be quite a trophy.", "那會是不錯的戰利品。"),
    ("I have plans for them.", "我對他們已有安排。"),
    ("The stakes have risen.", "賭注提高了。"),
    ("This one shall be worth the effort.", "這個值得費力。"),
    ("Let us see how many survive.", "看看有多少能活下來。"),
    ("I doubt it has wit to match its size.", "我懷疑它的智慧配不上它的個頭。"),
