    ("I slew the unnatural thing.", "我殺死了那非自然之物。"),
    ("Its feeble uncouth mind could not save it.", "它虛弱粗鄙的心智救不了它。"),
    ("Its walls are tumbled.", "它的牆已倒塌。"),
    ("Their vehicle lies in pieces.", "他們的載具碎成了片。"),
    ("I have laid the walker low.", "我已擊倒步行機。"),
    ("I am taking blows.", "我正在承受打擊。"),
    ("Allied Warp Spider incapacitated.", "盟友躍遷蜘蛛已失去戰鬥能力。"),
    ("My soul stone beckons.", "我的魂石在召喚。"),
    ("The shots came from that direction.", "射擊來自那個方向。"),
    ("The foe comes to meet me.", "敵人來與我交鋒。"),
    ("A close-quarters battle.", "近距離戰鬥。"),
    ("A teammate's Warboss has fallen.", "隊友的戰爭老大已倒下。"),
    ("An allied Mekboy has fallen.", "盟友技霸已倒下。"),
    ("Their psyker grows impertinent.", "他們的靈能者越發無禮。"),
    ("Our ally's Kommando has fallen.", "盟友特戰小子已倒下。"),
    ("Gouts of flame surround me.", "火焰噴流包圍了我。"),
    ("The Hive Tyrant of our ally has fallen.", "盟友的蟲巢暴君已倒下。"),
    ("An allied Ravener has been incapacitated.", "盟友劊子獸已失去戰鬥能力。"),
    ("A teammate's Lictor has fallen.", "隊友的利卡特已倒下。"),
    ("I am barricaded by their fire.", "我被他們的火力阻隔。"),
    ("The vehicle is targeting my cover.", "載具正在瞄準我的掩護。"),
    ("Our ally's headquarters has been destroyed.", "盟友總部已被摧毀。"),
    ("I am ready to serve.", "我準備效命。"),
    ("Beautifully lethal.", "美麗而致命。"),
    ("One of our Listening Posts has been destroyed.", "我們的一座監聽站已被摧毀。"),
    ("The splendor of the wraithbone augments my arm.", "幽冥骨的輝煌強化了我的手臂。"),
    ("I rage against the nightmares.", "我向噩夢傾瀉狂怒。"),
    ("I defy the corruption of the Great Enemy.", "我反抗大敵的腐化。"),
    ("Sing the battle songs again.", "再次唱起戰歌。"),
    ("If you would stop me, you must destroy me.", "若想阻止我，就必須摧毀我。"),
    ("This shape is well fitted for war.", "這形體非常適合戰爭。"),
    ("I never relent.", "我永不鬆懈。"),
    ("War is eternal.", "戰爭永恆。"),
    ("I cannot be deterred.", "我不會被阻止。"),
    ("You are our children. Dead though we are, we shall not abandon you.", "你們是我們的孩子。即便我們已死，也不會拋棄你們。"),
    ("Our race will endure.", "我們的種族將延續。"),
    ("Fear nothing. Your ancestors are here.", "無所畏懼。你的先祖就在此處。"),
    ("Even death is not our end.", "即便死亡也不是我們的終點。"),
    ("They are wise to fear the dead.", "他們畏懼死者是明智的。"),
    ("Look upon your doom.", "直視你的毀滅。"),
    ("Curse your gods and die.", "詛咒你的諸神，然後死吧。"),
    ("The very substance of this world will defy you.", "此世的本質都將反抗你。"),
    ("A bolt of killing light.", "一道殺戮之光。"),
    ("Let fly my lance.", "釋放我的光矛。"),
    ("Wrath from afar.", "遠方之怒。"),
    ("One last thrust.", "最後一刺。"),
    ("You would dare stand against me?", "你竟敢站出來對抗我？"),
    ("Be cast down.", "倒下吧。"),
    ("I shake the earth.", "我撼動大地。"),
    ("Back, creatures!", "退後，生物們！"),
    ("I cleave the defiant ones.", "我劈開反抗者。"),
    ("Taste the Wraith blade.", "嚐嚐幽冥之刃。"),
    ("Inexorable vengeance.", "不可阻擋的復仇。"),
    ("I would learn more of this species, but for now they must die.", "我本想多了解這個物種，但現在他們必須死。"),
    ("Benighted primitives. They shall not interfere.", "愚昧原始人。他們不得干涉。"),
    ("I do this for the living.", "我為生者而行。"),
    ("I go to slay.", "我去殺戮。"),
    ("I advance.", "我前進。"),
    ("I fight unto my last.", "我戰至最後。"),
    ("No sacrifice is too great.", "沒有犧牲過於巨大。"),
    ("I will lay them waste.", "我會將他們化為荒蕪。"),
    ("I continue the fight.", "我繼續戰鬥。"),
    ("Their weapons must be cast down.", "他們的武器必須被擊倒。"),
    ("That one's death will dismay the others.", "那個的死亡會使其他人驚恐。"),
    ("I shall thin their ranks.", "我會削減他們的隊列。"),
    ("I cannot allow such a beast to walk this world.", "我不能容許這樣的野獸行走於此世。"),
    ("They must be culled.", "他們必須被剔除。"),
    ("It must not reach the young ones.", "它絕不能接近年輕者。"),
    ("Its malformed mind will soon crumble.", "它畸形的心智很快會崩潰。"),
    ("I will raze the building.", "我會夷平那座建築。"),
    ("I will tear down what they have built.", "我會拆毀他們建造之物。"),
    ("I go to destroy it.", "我前去摧毀它。"),
    ("I will overturn it.", "我會推翻它。"),
    ("It shall not take another step.", "它不會再踏出一步。"),
    ("I shall teach them fear.", "我會教會他們恐懼。"),
    ("Drive back the noxious swarm.", "擊退有毒蟲群。"),
    ("An end to this travesty of life.", "終結這場生命的拙劣模仿。"),
    ("I will leave devastation in my wake.", "我會在身後留下毀滅。"),
    ("Where I go, none shall be spared.", "我所到之處，無人得赦。"),
    ("Any who oppose me shall die.", "凡反抗我者皆死。"),
    ("I must sweep away all hazards.", "我必須掃除一切危險。"),
    ("I return to slumber.", "我回歸沉眠。"),
    ("I can no longer resist the call of the infinite.", "我再也無法抗拒無限的召喚。"),
    ("My soul stone. Please take it.", "我的魂石。請帶走它。"),
    ("Save the others.", "拯救其他人。"),
    ("Old and young souls united in purpose.", "古老與年輕靈魂因共同目的而合一。"),
    ("We shall push back the Shadow.", "我們將擊退陰影。"),
    ("Do not spill Eldar blood in vain.", "不要讓靈族之血白流。"),
    ("For this I was raised?", "我被喚醒就是為了這個？"),
    ("For our people.", "為了我們的族人。"),
    ("Nothing in vain.", "一切都不會白費。"),
    ("I shall not hesitate.", "我不會猶豫。"),
    ("As you command.", "遵你命令。"),
    ("I will do this thing.", "我會完成此事。"),
    ("My work continues.", "我的工作繼續。"),
    ("When needs must.", "必要時如此。"),
    ("Yes, I shall.", "是，我會的。"),
    ("I obey the Farseer.", "我服從先知。"),
    ("At your order.", "聽你命令。"),
    ("As you desire.", "如你所願。"),
    ("My soul knows its purpose in these fallen times.", "在這墮落時代，我的靈魂知道自己的目的。"),
    ("The ways of war return to me.", "戰爭之道回到我身上。"),
    ("Now I remember!", "現在我想起來了！"),
    ("I see more clearly now.", "現在我看得更清楚。"),
    ("I will proceed.", "我會前進。"),
    ("I shall go.", "我會去。"),
    ("Wherever you wish me.", "去你希望我去的任何地方。"),
    ("I go as I am bid.", "我奉命而行。"),
    ("This body is not swift, but it will make the journey.", "這具軀體並不迅捷，但足以完成旅程。"),
    ("The enemy shall follow.", "敵人會跟上來。"),
    ("I have arrived as ordered.", "我已按命令抵達。"),
    ("I am leaving.", "我正在離開。"),
    ("It is but a step away.", "不過一步之遙。"),
    ("Well within reach.", "完全在可及範圍內。"),
    ("I will find it.", "我會找到它。"),
    ("I will not be turned aside.", "我不會被迫偏離。"),
    ("An abyss opens its jaws before me.", "深淵在我面前張開巨口。"),
    ("A chasm blocks me.", "裂谷阻擋了我。"),
    ("I cannot see the way.", "我看不見道路。"),
    ("I cannot continue.", "我無法繼續。"),
    ("I shall withdraw.", "我會撤離。"),
    ("It must suffice for now.", "暫時只能如此。"),
    ("Targeting tunnel entrance.", "正在瞄準隧道入口。"),
    ("I must disengage.", "我必須脫離。"),
    ("Give me a task.", "給我任務。"),
    ("What is my purpose?", "我的目的為何？"),
    ("Even now I serve.", "即便如今，我仍效命。"),
    ("I hear you.", "我聽見你。"),
    ("What must be?", "何事必須成真？"),
    ("I endure.", "我承受。"),
    ("I have not endured eons of silence only to see our children slaughtered.", "我忍受萬古寂靜，不是為了看我們的孩子被屠殺。"),
    ("Do not give the enemy the gift of fear.", "不要把恐懼這份禮物送給敵人。"),
    ("This world has changed much since I last beheld it.", "自我上次凝視此世以來，它已改變許多。"),
    ("Tell me of your Craftworld. Is it very beautiful?", "告訴我你的方舟世界。它很美嗎？"),
    ("Nightmares torment me!", "噩夢折磨著我！"),
    ("I must expect the living to be impatient.", "我應該料到生者會缺乏耐心。"),
    ("A tool, at the time it is needed, is a treasure.", "在需要之時，工具便是珍寶。"),
    ("This might be a potent aid to our efforts.", "這或許能大力幫助我們。"),
    ("This seems an ideal place for occupation.", "這似乎是理想的佔據地點。"),
    ("I sense a place of power.", "我感知到一處力量之地。"),
    ("More Eldar are here.", "更多靈族在此。"),
    ("Brother and sister souls.", "兄弟與姐妹的靈魂。"),
    ("They are somewhat like us in shape, but not in thought.", "他們形體上略似我們，思想上卻不是。"),
    ("And it is these that have built a vast Imperium?", "就是這些東西建立了龐大帝國？"),
    ("The green-skinned ones.", "那些綠皮者。"),
    ("The Orkish scavengers.", "獸人拾荒者。"),
    ("I see forces arrayed against us.", "我看見部隊列陣對抗我們。"),
    ("It is our foe. Shall I remove them?", "那是我們的敵人。要我清除他們嗎？"),
    ("They have come heavily armed.", "他們全副武裝而來。"),
    ("This one has a commanding air.", "這個有指揮者的氣勢。"),
    ("Enemy footsoldiers.", "敵方步兵。"),
    ("A beast, shaped like a warp-daemon.", "一頭形似亞空間惡魔的野獸。"),
    ("It makes a childish attempt to read my mind.", "它幼稚地試圖讀取我的心智。"),
    ("A fast-moving foe.", "快速移動的敵人。"),
    ("It walks, but it has not the grace of my Wraithbone.", "它能行走，卻沒有我的幽冥骨那般優雅。"),
    ("The humans' armored elite are here.", "人類披甲精銳在此。"),
    ("They are twisted by the mind they serve.", "他們被自己侍奉的心智所扭曲。"),
    ("I feel the horror they bring well before I see them.", "在看見他們之前，我已感覺到他們帶來的恐怖。"),
    ("I remain here.", "我留在此處。"),
    ("A respite.", "一段喘息。"),
    ("I await orders.", "我等待命令。"),
    ("I shall stand aside.", "我會退到一旁。"),
    ("I attack only at your word.", "只要你下令，我才攻擊。"),
    ("A halt is called.", "已下令停止。"),
    ("I have rendered you aid.", "我已向你提供援助。"),
    ("That target is no more.", "那個目標不復存在。"),
    ("Their heavy arms shatter.", "他們的重武器粉碎了。"),
    ("Its will was strong, but no more.", "它的意志曾經強大，但如今不再。"),
    ("Their tiny souls fray.", "他們渺小的靈魂正在磨損。"),
    ("I have trampled them underfoot.", "我已將他們踩在腳下。"),
    ("I have butchered the abomination.", "我已屠宰那憎惡之物。"),
    ("Their foolish psyker has met his deserved fate.", "他們愚蠢的靈能者迎來了應得命運。"),
    ("I have razed the enemy structure.", "我已夷平敵方建築。"),
    ("I have crushed the vehicle.", "我已壓碎那輛載具。"),
    ("I have made an end of their stumbling contraption.", "我已終結他們那台踉蹌的破裝置。"),
    ("What they build, I destroy.", "他們建造的，我摧毀。"),
    ("I have laid their building to waste.", "我已將他們的建築化為荒廢。"),
    ("It will chase us no longer.", "它不會再追逐我們。"),
    ("Their vehicle lies devastated.", "他們的載具已徹底毀壞。"),
    ("I feel a storm of attack.", "我感到攻擊風暴。"),
    ("They fire upon me.", "他們朝我開火。"),
    ("They batter upon me.", "他們猛擊我。"),
    ("The enemy's mockery lumbers toward me now.", "敵人那嘲弄之物正笨重地向我走來。"),
    ("Delicate creatures -- but their weapons bite.", "脆弱生物，但他們的武器會咬人。"),
    ("They besiege me, yet I can feel their trepidation.", "他們圍攻我，但我能感到他們的恐懼。"),
    ("Barbaric Orks strike at me.", "野蠻獸人正在攻擊我。"),
    ("It seems this body is not invulnerable.", "看來這具軀體並非無敵。"),
    ("Their blows rain heavy.", "他們的打擊沉重如雨。"),
    ("My Wraithbone cracks.", "我的幽冥骨開裂了。"),
    ("My vision fogs. What assails me?", "我的視野模糊了。什麼在攻擊我？"),
    ("Something besets me, but I cannot see it.", "有東西纏住了我，但我看不見它。"),
    ("I feel hate from an alien mind.", "我感到來自異族心智的憎恨。"),
    ("Their cannonade is firing.", "他們的炮擊正在開火。"),
    ("It pierces my Wraithbone with ease.", "它輕易刺穿我的幽冥骨。"),
    ("It seems that war is their religion, and they wish to make their devotions.", "看來戰爭就是他們的宗教，而他們想要獻上虔敬。"),
    ("These humans do not fear me.", "這些人類不怕我。"),
    ("The swarm is upon me.", "蟲群逼近我了。"),
    ("The horror speaks.", "那恐怖之物在說話。"),
    ("You call me again from afar.", "你又從遠方呼喚我。"),
    ("I will serve the Eldar again.", "我將再次為靈族效命。"),
    ("My service is not yet at its end.", "我的效命尚未結束。"),
    ("Once, my name was Elothan.", "曾經，我名為埃洛桑。"),
    ("Let the living tremble before the Wraithlord.", "讓生者在幽冥領主面前顫抖。"),
    ("This world seems distant, but I walk it again.", "此世似乎遙遠，但我再次行走其上。"),
    ("I shall rain razored death upon the enemy.", "我將向敵人降下剃刀般的死亡。"),
    ("I will wield this lance as though Vaul himself had forged it.", "我會揮使這柄光矛，如同沃爾親手鍛造它。"),
    ("The Wraithbone grows around me.", "幽冥骨在我周圍生長。"),
    ("I have been reshaped for new tasks.", "我已被重塑，以承擔新任務。"),
    ("This body has changed.", "這具軀體已改變。"),
    ("You clothe me in the power of the Eldar.", "你以靈族之力為我披甲。"),
    ("Strange that there is no pain.", "奇怪，竟沒有痛苦。"),
    ("My sight in this world dims.", "我在此世的視野正在黯淡。"),
    ("I cannot move.", "我無法移動。"),
    ("My weapons fail me.", "我的武器辜負了我。"),
    ("No blundering creature shall invade *my* mind.", "沒有笨拙生物能侵入我的心智。"),
    ("Their structure shall fall.", "他們的建築將會倒塌。"),
    ("It is necessary to remove their vehicle.", "必須移除他們的載具。"),
    ("To the end which is bitter.", "走向苦澀的終點。"),
    ("We shall see who dies first.", "我們會看看誰先死。"),
    ("They are still only humans.", "他們終究只是人類。"),
    ("They profane the very name of life.", "他們褻瀆了生命之名。"),
    ("None shall stop us, Farseer.", "無人能阻止我們，先知。"),
    ("Nothing shall deny us.", "沒有什麼能拒絕我們。"),
    ("Weapons drawn.", "武器出鞘。"),
    ("We shall engage as needed.", "我們將按需交戰。"),
    ("Travel light. The foe may be many.", "輕裝前行。敵人或許眾多。"),
    ("The road of the Eldar is long and fraught with peril.", "靈族之路漫長且危機四伏。"),
    ("Another door open into the Webway.", "另一扇通往網道的門開啟。"),
    ("The weapons platform is in place.", "武器平台已就位。"),
    ("What the Bonesingers have prepared we shall receive.", "骨歌者所準備之物，我們將接受。"),
    ("The Bonesong is complete.", "骨歌已完成。"),
    ("Deploy the Wraithbone.", "部署幽冥骨。"),
    ("We shall acquire it.", "我們會取得它。"),
    ("We have succeeded in our objective.", "我們已成功完成目標。"),
    ("Behold our new possession.", "看我們的新所有物。"),
    ("We have it, Farseer.", "我們得到了，先知。"),
    ("We have taken a trophy.", "我們奪得一件戰利品。"),
    ("We cannot fail.", "我們不能失敗。"),
    ("Closing in on the objective.", "正在逼近目標。"),
    ("Consider the territory in our hands.", "將此領土視為已在我們手中。"),
    ("Give it not a moment's thought.", "不必為此多想片刻。"),
    ("We will capture it.", "我們會佔領它。"),
    ("It will serve the Craftworld well.", "它會很好地服務方舟世界。"),
    ("We stand upon newly gained ground.", "我們站在新取得的土地上。"),
    ("Sing the songs of war!", "唱響戰歌！"),
    ("Strike swiftly and true", "迅速而精準地打擊"),
    ("To battle my kin", "投入戰鬥，我的同族"),
    ("They have no hope of survival.", "他們沒有生還希望。"),
    ("We will cut a swath through their ranks.", "我們會在他們隊列中劈開一條血路。"),
    ("Khaine will be pleased with our onslaught", "凱恩會因我們的猛攻而愉悅"),
    ("Give the enemy no quarter", "對敵人絕不留情"),
    ("They will be utterly destroyed.", "他們將被徹底摧毀。"),
    ("Their existence is a momentary distraction.", "他們的存在只是片刻干擾。"),
    ("They shall feel our wrath.", "他們將感受我們的怒火。"),
    ("Into the fray!", "衝入戰局！"),
    ("You will die by Eldar hands", "你將死於靈族之手"),
    ("Prepare to meet your end", "準備迎接你的終結"),
    ("Why will you not die?", "你為何還不死？"),
    ("Exterminate them", "滅絕他們"),
    ("We must prevail", "我們必須取勝"),
    ("Take the battle to the enemy", "將戰鬥帶向敵人"),
    ("Fall upon them with bladed fury!", "以利刃狂怒撲向他們！"),
    ("Bringing our superior weapons to bear", "發揮我們優越武器的威力"),
    ("Our weapons cut through them like a blade through air.", "我們的武器切開他們，如刀刃劃過空氣。"),
    ("Bringing full weaponry to bear.", "發揮全部武器威力。"),
    ("On this day we walk the Path of War!", "今日我們行於戰爭之道！"),
    ("You to the left flank, I to the right.", "你去左翼，我去右翼。"),
    ("I see no need to keep count.", "我看不必計數。"),
    ("Mind your tongue. The Farseer is surely watching.", "注意言辭。先知肯定在看著。"),
    ("Even the Exarchs will admire a shot such as that.", "連大能者也會欣賞那樣的一擊。"),
    ("An infusion of old souls will bring hope to the Craftworld.", "古老靈魂的注入將為方舟世界帶來希望。"),
    ("Idleness is dangerous for Eldar minds.", "閒散對靈族心智很危險。"),
    ("Strange not to have the Wraithbone singing beneath my feet. How do the Exodites stand it?", "腳下沒有幽冥骨歌唱真奇怪。蠻荒靈族怎麼忍受得了？"),
    ("Far flung are we Eldar, and I dare not think we shall ever reunite.", "我們靈族分散遙遠，我不敢想我們是否還會重聚。"),
    ("I will return to silent meditations when we return to the Craftworld.", "等回到方舟世界，我會回歸靜默冥想。"),
    ("Let us have a song to ease our time.", "讓我們唱首歌打發時間。"),
    ("He is too wounded. Look to his soul stone.", "他傷得太重。照看他的魂石。"),
    ("No, I shall not leave your side.", "不，我不會離開你身邊。"),
    ("It is as Veldoran said, we will die in this cursed land.", "正如維爾多蘭所說，我們會死在這片受詛之地。"),
    ("Be still. Do not try to speak now.", "別動。現在不要試著說話。"),
    ("I may die, though my soul will endure.", "我或許會死，但我的靈魂會延續。"),
    ("Keep watching the horizon.", "繼續注視地平線。"),
    ("The Exodites have done poor work as stewards in this sector.", "蠻荒靈族作為此區域的管護者做得很差。"),
