    ("We can hear you.", "我們聽得見你。"),
    ("What do you wish of us?", "你希望我們做什麼？"),
    ("Let us hope our voyage does not end like Lord Elothan's.", "願我們的航程不會像埃洛桑領主那樣結束。"),
    ("Do our ancestors' bones truly grace these miserable worlds?", "我們先祖的遺骨真的榮耀著這些悲慘世界嗎？"),
    ("Our purpose is sacred, but it will cost humble flesh dear.", "我們的目的神聖，但卑微血肉將付出沉重代價。"),
    ("Careful. There are enemy there.", "小心。那裡有敵人。"),
    ("We have found their heavy guns.", "我們找到他們的重炮了。"),
    ("We have spotted a group of infantry.", "我們發現了一群步兵。"),
    ("We hope for new orders,", "我們期待新命令，"),
    ("Call the halt.", "下令停止。"),
    ("We await word.", "我們等待指示。"),
    ("Break off the attack.", "停止攻擊。"),
    ("The attack order is rescinded.", "攻擊命令已撤銷。"),
    ("We have cost them their weapons.", "我們讓他們失去了武器。"),
    ("A stubborn foe, but we prevailed.", "頑強的敵人，但我們取勝了。"),
    ("Casualties of their masters' mistakes.", "他們主子錯誤的犧牲品。"),
    ("We slew the unnatural thing.", "我們殺死了那非自然之物。"),
    ("We have laid the walker low.", "我們已擊倒步行機。"),
    ("The foe come to meet us.", "敵人來與我們交鋒。"),
    ("They have a clear shot at us.", "他們對我們有清晰射擊線。"),
    ("We are easy prey here.", "我們在這裡是容易的獵物。"),
    ("Their artillery rains upon us.", "他們的炮火如雨落下。"),
    ("Gouts of flame surround us.", "火焰噴流包圍了我們。"),
    ("We swim against a tide of fire.", "我們逆著火潮前行。"),
    ("They have set their vehicle on us.", "他們派載具來對付我們。"),
    ("Our cover may fail under the bombardment.", "我們的掩護可能在轟炸下失效。"),
    ("Assassins.", "刺客。"),
    ("We are ready to serve.", "我們準備效命。"),
    ("New strength from greater numbers.", "更多人數帶來新的力量。"),
    ("The foe press us too hard.", "敵人逼得太緊。"),
    ("We cannot hold out much longer.", "我們撐不了多久了。"),
    ("Our arsenal increases.", "我們的武庫擴充了。"),
    ("They will serve their deadly function.", "它們將發揮致命作用。"),
    ("Let us put these new arms to the test.", "讓我們測試這些新武器。"),
    ("We shall wield them with ardor.", "我們將熱切地揮使它們。"),
    ("Even our voices are death.", "連我們的聲音都是死亡。"),
    ("Our cry of hate.", "我們的仇恨呼喊。"),
    ("To your knees, worm.", "跪下，蟲子。"),
    ("Share my agony.", "分享我的痛苦。"),
    ("Fleet and sure.", "迅捷而堅定。"),
    ("Like a howling wind.", "如嚎叫之風。"),
    ("More cautiously now.", "現在更謹慎些。"),
    ("Overhaste is dangerous.", "過度急躁很危險。"),
    ("The furies are unleashed.", "狂怒已被釋放。"),
    ("Already upon you.", "已經逼近你。"),
    ("Let us dance.", "讓我們起舞。"),
    ("Into the teeth of death.", "直入死亡之口。"),
    ("Press them hard.", "狠狠壓迫他們。"),
    ("Nothing shall stand before me. Or after.", "沒有什麼能擋在我面前。或留在我身後。"),
    ("Cut it to ribbons.", "把它切成碎片。"),
    ("I want them to see my eyes.", "我要他們看見我的眼睛。"),
    ("Let us give it something to shoot at.", "讓我們給它一個可射擊的目標。"),
    ("Destroy it before it shoots us down.", "在它擊落我們前摧毀它。"),
    ("Most certainly.", "當然。"),
    ("We cannot let them stop us.", "我們不能讓他們阻止我們。"),
    ("We abide by the Farseer's wisdom.", "我們遵循先知的智慧。"),
    ("By the Crone.", "以老嫗之名。"),
    ("We are the Banshee.", "我們是女妖。"),
    ("I would rather be avenged than mourned.", "我寧願被復仇，而非被哀悼。"),
    ("Tell us our task.", "告訴我們任務。"),
    ("We would do our Temple honor.", "我們願榮耀神殿。"),
    ("Yes, come at me.", "是，衝我來。"),
    ("Their blows are vicious.", "他們的打擊很兇狠。"),
    ("They assail us from afar.", "他們從遠處攻擊我們。"),
    ("They fire upon our wounded.", "他們朝我們的傷者開火。"),
    ("We must find cover somewhere.", "我們必須找地方掩護。"),
    ("This is a tenuous position.", "這位置很脆弱。"),
    ("Our protection is put to the test.", "我們的防護正受考驗。"),
    ("Their guns slow our advance.", "他們的槍炮拖慢我們前進。"),
    ("The barrage is overwhelming.", "彈幕壓倒一切。"),
    ("We are caught in a tide of enemy fire.", "我們陷入敵方火力浪潮。"),
    ("They wish to imprison us in our cover.", "他們想把我們困在掩護中。"),
    ("They were lying in wait for us.", "他們埋伏等著我們。"),
    ("I cannot see the assassin.", "我看不見刺客。"),
    ("A cowardly assault!", "懦夫的攻擊！"),
    ("An ambush. Stay under cover.", "伏擊。留在掩護下。"),
    ("Let our enemies forgo all hope, for the Banshee howls their doom.", "讓敵人放棄一切希望，因女妖嚎出他們的毀滅。"),
    ("Another voice joins our chorus.", "又一個聲音加入我們的合唱。"),
    ("These blades are finely balanced.", "這些刀刃平衡精妙。"),
    ("This keen edge shall cleave many foes.", "這鋒銳刃口將劈開眾多敵人。"),
    ("Now both hands bear witness to my wrath.", "現在雙手都將見證我的怒火。"),
    ("The sacred triskele, herald of vengeance.", "神聖三曲刃，復仇的先聲。"),
    ("With these we shall strike the enemy's heart cold.", "憑藉這些，我們將讓敵人的心冷卻。"),
    ("Let us put these battle-trappings to the test.", "讓我們測試這些戰鬥裝備。"),
    ("I come to remove all hope.", "我來奪走一切希望。"),
    ("Why prolong your agony?", "何必延長你的痛苦？"),
    ("It will be easier if you do not struggle.", "若你不掙扎，一切會容易些。"),
    ("You will succumb.", "你會屈服。"),
    ("Drown in my wrath.", "溺死於我的怒火。"),
    ("Call the tempest.", "召喚風暴。"),
    ("Witness the storm.", "見證風暴。"),
    ("The turmoil of my mind is manifest.", "我心智的動盪顯現了。"),
    ("Nothing is stronger than the Eldar will.", "沒有什麼比靈族意志更強。"),
    ("The ancients shall reward our constancy.", "先祖將獎賞我們的堅定。"),
    ("Remember the vision.", "銘記幻象。"),
    ("We must carry on.", "我們必須繼續。"),
    ("Let us join minds and courage.", "讓我們合一心智與勇氣。"),
    ("Ancestors guide our hands.", "先祖指引我們的雙手。"),
    ("Strike without fear.", "無懼出擊。"),
    ("Remain undaunted always.", "永遠無畏。"),
    ("I will undo their very thoughts.", "我會瓦解他們的思想本身。"),
    ("My will is my weapon.", "我的意志就是武器。"),
    ("Let us contend on a higher battlefield.", "讓我們在更高層面的戰場較量。"),
    ("A volley of pure hatred.", "一輪純粹仇恨的齊射。"),
    ("I will convey our 'message.'", "我會傳達我們的「信息」。"),
    ("Have at them.", "上吧。"),
    ("I must end this.", "我必須終結此事。"),
    ("Hands that kill can also cure.", "殺戮之手亦可治癒。"),
    ("The healing cannot wait.", "治療不能等待。"),
    ("An infusion of life.", "生命的注入。"),
    ("Strength from desperation.", "絕境中生出的力量。"),
    ("They have much to answer for.", "他們有許多罪責要承擔。"),
    ("We must match them in cruelty.", "我們必須以同等殘酷回應。"),
    ("I shall show them the fruits of the Witch Path.", "我會讓他們見識巫道的成果。"),
    ("My particular gifts are called for.", "此處需要我獨有的天賦。"),
    ("It shall be so.", "必將如此。"),
    ("I serve readily.", "我樂意效命。"),
    ("As the vision requires.", "如幻象所需。"),
    ("It is fated to be.", "這是命中注定。"),
    ("All is not well here.", "此處並非一切安好。"),
    ("Do not fear to speak your mind.", "不要害怕說出你的想法。"),
    ("The skeins of fate are tangled.", "命運之線纏結在一起。"),
    ("The foe is unleashed upon me.", "敵人向我釋放了攻勢。"),
    ("The enemy is firing.", "敵人正在開火。"),
    ("The enemy fire is brutal.", "敵方火力很殘酷。"),
    ("I must seek a hiding place.", "我必須尋找藏身處。"),
    ("They see that my cover is weak.", "他們看出我的掩護薄弱。"),
    ("I must trust this cover to hold.", "我必須相信這掩護撐得住。"),
    ("Your fellow seer is arrived.", "你的先知同道已抵達。"),
    ("I answer destiny's call.", "我回應命運召喚。"),
    ("I shall gladly bring it forth in battle.", "我會樂意在戰鬥中展現它。"),
    ("The Witchblade is mine.", "巫刃歸我。"),
    ("Let these runes awake.", "讓這些符文甦醒。"),
    ("Tiny, deadly messengers.", "微小而致命的信使。"),
    ("May these spears fly far and true.", "願這些長矛飛得又遠又準。"),
    ("My will overpowers all!", "我的意志壓倒一切！"),
    ("They are flotsam in the psychic sea.", "他們是靈能之海中的漂流物。"),
    ("Isha -- bless this ground.", "伊莎，祝福此地。"),
    ("Let the runes mark this as Eldar land.", "讓符文標記此地為靈族土地。"),
    ("There is power within.", "其中蘊藏力量。"),
    ("The land shall scorch and burn!", "大地將焦灼燃燒！"),
    ("Step into the Forge of Vaul!", "踏入沃爾熔爐！"),
    ("My time has come at last.", "我的時刻終於到了。"),
    ("You who have paths yet to walk, return.", "仍有道途要走的人，回來。"),
    ("The might of Khaine fills me!", "凱恩的威能充盈我身！"),
    ("They shall feel the might of a true Warlock on this day!", "今日他們將感受真正術士的威能！"),
    ("Away from me!", "離我遠點！"),
    ("Targeting the Ork.", "正在瞄準獸人。"),
    ("Now, into the Space Marines!", "現在，衝向星際戰士！"),
