    ("I shall purge that obscenity.", "我會淨化那褻瀆之物。"),
    ("I shall bring down their post.", "我會摧毀他們的哨站。"),
    ("Attacking structure.", "正在攻擊建築。"),
    ("Clear the obstacle.", "清除障礙。"),
    ("That target is out of our range.", "那目標超出我們射程。"),
    ("Our weapons will not reach him from here.", "我們的武器從這裡打不到他。"),
